from fastapi import FastAPI, HTTPException
from fastapi.responses import RedirectResponse
from fastapi import Response
from pydantic import BaseModel
import random
import string
from datetime import datetime

app = FastAPI()

# In-memory storage
url_storage = {}
click_stats = {}

class ShortenRequest(BaseModel):
    long_url: str

class ShortenResponse(BaseModel):
    short_code: str

class StatsResponse(BaseModel):
    clicks: int

class HealthResponse(BaseModel):
    status: str
    timestamp: str

def generate_short_code(length=6):
    characters = string.ascii_letters + string.digits
    return ''.join(random.choice(characters) for _ in range(length))

@app.post("/shorten", response_model=ShortenResponse)
async def shorten_url(request: ShortenRequest):
    short_code = generate_short_code()
    url_storage[short_code] = request.long_url
    click_stats[short_code] = 0
    return ShortenResponse(short_code=short_code)

@app.get("/{short_code}", response_class=RedirectResponse, status_code=307)
async def redirect_url(short_code: str):
    long_url = url_storage.get(short_code)
    if long_url is None:
        raise HTTPException(status_code=404, detail="URL not found")
    click_stats[short_code] += 1
    return RedirectResponse(url=long_url)

@app.get("/stats/{short_code}", response_model=StatsResponse)
async def get_stats(short_code: str):
    clicks = click_stats.get(short_code, 0)
    return StatsResponse(clicks=clicks)

@app.get("/health", response_model=HealthResponse)
async def health_check():
    return HealthResponse(status="healthy", timestamp=datetime.utcnow().isoformat())

from fastapi import FastAPI, HTTPException
from fastapi.responses import RedirectResponse
from pydantic import BaseModel
from typing import Dict
import time

app = FastAPI()

# In-memory storage for URLs
url_storage: Dict[str, str] = {}
click_counter: Dict[str, int] = {}

class ShortenRequest(BaseModel):
    long_url: str

class ShortenResponse(BaseModel):
    short_code: str

class StatsResponse(BaseModel):
    clicks: int

class HealthResponse(BaseModel):
    status: str
    timestamp: str

@app.post("/shorten", response_model=ShortenResponse)
def shorten_url(request: ShortenRequest):
    short_code = str(len(url_storage) + 1)  # Simple incremental short code
    url_storage[short_code] = request.long_url
    click_counter[short_code] = 0
    return ShortenResponse(short_code=short_code)

@app.get("/{short_code}", response_class=RedirectResponse, status_code=307)
def redirect_to_long_url(short_code: str):
    long_url = url_storage.get(short_code)
    if long_url is None:
        raise HTTPException(status_code=404, detail="Short code not found")
    click_counter[short_code] += 1
    return RedirectResponse(url=long_url)

@app.get("/stats/{short_code}", response_model=StatsResponse)
def get_stats(short_code: str):
    clicks = click_counter.get(short_code, 0)
    return StatsResponse(clicks=clicks)

@app.get("/health", response_model=HealthResponse)
def health_check():
    return HealthResponse(status="healthy", timestamp=time.strftime("%Y-%m-%d %H:%M:%S"))
